"""Embed the original PNGs for exports when index.html is opened with file://."""

import base64
import json
from pathlib import Path

drawings = Path(__file__).resolve().parents[1] / "drawings"
images = {
    png.name: "data:image/png;base64," + base64.b64encode(png.read_bytes()).decode("ascii")
    for png in sorted(drawings.glob("*.png"))
}
output = drawings / "local-linework.js"
output.write_text(
    "// Generated by tools/build-local-linework.py from drawings/*.png.\n"
    "window.childcolorLocalLinework = " + json.dumps(images, indent=2) + ";\n",
    encoding="utf-8",
)
